arguments.cmd:
cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ScreenVault — UI & UX Design Inspiration Library</title>
  <meta name="description" content="Save hours of UI & UX research with 400,000+ searchable mobile and web app screenshots, flows, and UI patterns." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: oklch(0.99 0.004 255);
      --surface: oklch(1 0 0);
      --surface-2: oklch(0.97 0.004 255);
      --text: oklch(0.19 0.02 265);
      --text-muted: oklch(0.48 0.02 265);
      --border: oklch(0.9 0.008 265);
      --primary: oklch(0.61 0.24 271);
      --primary-strong: oklch(0.54 0.25 271);
      --primary-soft: oklch(0.95 0.03 271);
      --ring: oklch(0.7 0.18 271);
      --shadow-sm: 0 1px 2px color-mix(in oklab, black 8%, transparent);
      --shadow-md: 0 8px 24px color-mix(in oklab, black 10%, transparent);
      --radius-sm: 10px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --ease: cubic-bezier(0.2, 0.8, 0.2, 1);
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: radial-gradient(1200px 600px at 10% -10%, oklch(0.96 0.04 271), transparent), var(--bg);
      color: var(--text);
      line-height: 1.5;
    }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(1120px, calc(100% - 2rem));
      margin-inline: auto;
    }

    .announcement {
      font-size: 0.9rem;
      background: var(--surface);
      border-bottom: 1px solid var(--border);
      color: var(--text-muted);
    }
    .announcement .inner {
      height: 46px;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.55rem;
      text-align: center;
      flex-wrap: wrap;
    }
    .badge {
      background: var(--primary-soft);
      color: var(--primary-strong);
      border: 1px solid color-mix(in oklab, var(--primary) 25%, white);
      padding: 0.2rem 0.55rem;
      border-radius: 999px;
      font-size: 0.76rem;
      font-weight: 600;
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(10px);
      background: color-mix(in oklab, white 90%, transparent);
      border-bottom: 1px solid color-mix(in oklab, var(--border) 85%, white);
    }
    .nav {
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 0.62rem;
      font-weight: 700;
      letter-spacing: -0.02em;
    }
    .logo-mark {
      width: 30px;
      height: 30px;
      border-radius: 9px;
      background: linear-gradient(140deg, var(--primary), oklch(0.75 0.19 248));
      box-shadow: var(--shadow-sm);
    }
    .nav-links {
      display: flex;
      gap: 1.25rem;
      color: var(--text-muted);
      font-size: 0.93rem;
      font-weight: 500;
    }
    .nav-links a,
    .link-inline {
      transition: color 220ms var(--ease);
    }
    .nav-links a:hover,
    .link-inline:hover { color: var(--text); }

    .nav-cta {
      display: flex;
      align-items: center;
      gap: 0.85rem;
    }

    .btn {
      border: 0;
      border-radius: 12px;
      min-height: 44px;
      padding: 0.72rem 1.15rem;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 160ms var(--ease), box-shadow 220ms var(--ease), background 220ms var(--ease), color 220ms var(--ease);
    }
    .btn:focus-visible,
    .pill:focus-visible,
    .tab:focus-visible,
    .toggle-btn:focus-visible,
    .link-button:focus-visible,
    .nav-links a:focus-visible,
    .link-inline:focus-visible {
      outline: 3px solid color-mix(in oklab, var(--ring) 65%, white);
      outline-offset: 2px;
    }
    .btn-primary {
      background: var(--primary);
      color: white;
      box-shadow: 0 8px 20px color-mix(in oklab, var(--primary) 45%, transparent);
    }
    .btn-primary:hover { background: var(--primary-strong); transform: translateY(-1px); }
    .btn-primary:active { transform: translateY(0) scale(0.98); }

    .btn-ghost {
      background: transparent;
      color: var(--text-muted);
    }
    .btn-ghost:hover { color: var(--text); background: var(--surface-2); }

    .hero {
      padding: 5rem 0 3.5rem;
      text-align: center;
    }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      border: 1px solid var(--border);
      background: var(--surface);
      border-radius: 999px;
      padding: 0.3rem 0.7rem;
      color: var(--text-muted);
      font-size: 0.84rem;
      font-weight: 500;
    }
    .hero h1 {
      margin: 1rem auto 1rem;
      max-width: 900px;
      font-size: clamp(2rem, 4vw, 3.8rem);
      line-height: 1.06;
      letter-spacing: -0.04em;
      text-wrap: balance;
    }
    .hero p {
      margin: 0 auto;
      max-width: 740px;
      color: var(--text-muted);
      font-size: clamp(1rem, 2vw, 1.18rem);
      text-wrap: balance;
    }
    .hero-actions {
      margin-top: 1.8rem;
      display: flex;
      justify-content: center;
      gap: 0.9rem;
      flex-wrap: wrap;
    }
    .hero-card {
      margin-top: 2.5rem;
      padding: 1rem;
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      background: color-mix(in oklab, var(--surface) 92%, #eef1ff);
      box-shadow: var(--shadow-md);
    }
    .preview-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.85rem;
    }
    .preview-item {
      aspect-ratio: 4 / 3;
      border-radius: var(--radius-md);
      border: 1px solid color-mix(in oklab, var(--border) 85%, white);
      background: linear-gradient(145deg, #fff, #f6f7fc);
      position: relative;
      overflow: hidden;
    }
    .preview-item::before {
      content: "";
      position: absolute;
      inset: 10% 8%;
      border-radius: 8px;
      background: linear-gradient(180deg, #ffffff, #f2f4ff);
      border: 1px solid #e5e9ff;
    }
    .preview-item::after {
      content: "";
      position: absolute;
      left: 14%;
      right: 14%;
      height: 7px;
      bottom: 15%;
      border-radius: 999px;
      background: color-mix(in oklab, var(--primary) 30%, white);
    }

    section { padding: 3.3rem 0; }

    .section-head {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.3rem;
    }
    .section-head h2 {
      margin: 0;
      font-size: clamp(1.4rem, 2.8vw, 2.15rem);
      letter-spacing: -0.03em;
    }
    .section-head p {
      margin: 0;
      color: var(--text-muted);
      max-width: 600px;
    }

    .trusted-track-wrap {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      overflow: hidden;
      padding: 1rem 0;
    }

    .marquee {
      --duration: 26s;
      display: flex;
      overflow: hidden;
      user-select: none;
      mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
    }
    .marquee-content {
      display: flex;
      flex-shrink: 0;
      min-width: 100%;
      animation: scroll var(--duration) linear infinite;
    }
    .marquee.reverse .marquee-content { animation-direction: reverse; }

    .brand-chip {
      margin-inline: 0.75rem;
      border: 1px solid var(--border);
      background: linear-gradient(180deg, #fff, #fafbff);
      color: var(--text-muted);
      border-radius: 999px;
      font-weight: 600;
      font-size: 0.9rem;
      padding: 0.6rem 1rem;
      white-space: nowrap;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }
    .stat {
      border-radius: var(--radius-lg);
      background: var(--surface);
      border: 1px solid var(--border);
      padding: 1.4rem;
      box-shadow: var(--shadow-sm);
    }
    .stat-value {
      font-size: clamp(1.9rem, 4vw, 2.8rem);
      font-weight: 800;
      letter-spacing: -0.04em;
      margin: 0;
    }
    .stat-label { margin: 0.25rem 0 0; color: var(--text-muted); }

    .feature-shell {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      box-shadow: var(--shadow-sm);
      padding: 1.1rem;
    }

    .tabs {
      display: flex;
      gap: 0.55rem;
      flex-wrap: wrap;
      margin-bottom: 1rem;
    }
    .tab {
      border: 1px solid var(--border);
      background: var(--surface-2);
      color: var(--text-muted);
      border-radius: 999px;
      min-height: 40px;
      padding: 0.45rem 0.9rem;
      font: inherit;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      transition: all 240ms var(--ease);
    }
    .tab.active {
      background: var(--primary-soft);
      border-color: color-mix(in oklab, var(--primary) 25%, white);
      color: var(--primary-strong);
    }

    .filters {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
      margin-bottom: 1rem;
    }
    .pill {
      border: 1px solid var(--border);
      background: var(--surface);
      color: var(--text-muted);
      border-radius: 999px;
      min-height: 36px;
      padding: 0.3rem 0.72rem;
      font: inherit;
      font-size: 0.82rem;
      font-weight: 600;
      cursor: pointer;
      transition: all 240ms var(--ease);
    }
    .pill.active {
      background: color-mix(in oklab, var(--primary) 10%, white);
      color: var(--primary-strong);
      border-color: color-mix(in oklab, var(--primary) 35%, white);
      transform: translateY(-1px);
    }

    .results-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.75rem;
      min-height: 210px;
    }
    .result-card {
      border: 1px solid var(--border);
      background: linear-gradient(160deg, #fff, #f6f8ff);
      border-radius: 12px;
      padding: 0.6rem;
      opacity: 0;
      transform: translateY(8px);
      animation: fadeUp 300ms var(--ease) forwards;
    }
    .result-thumb {
      height: 82px;
      border-radius: 9px;
      background: linear-gradient(180deg, #ffffff, #eff2ff);
      border: 1px solid #e6eafe;
      margin-bottom: 0.55rem;
      position: relative;
      overflow: hidden;
    }
    .result-thumb::before {
      content: "";
      position: absolute;
      top: 12px;
      left: 10px;
      width: 50%;
      height: 6px;
      border-radius: 999px;
      background: #dce3ff;
    }
    .result-thumb::after {
      content: "";
      position: absolute;
      bottom: 12px;
      left: 10px;
      right: 10px;
      height: 20px;
      border-radius: 7px;
      background: color-mix(in oklab, var(--primary) 18%, white);
    }
    .result-meta {
      font-size: 0.75rem;
      color: var(--text-muted);
      display: flex;
      justify-content: space-between;
      gap: 0.5rem;
    }

    .flows-box {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      padding: 1.1rem;
      box-shadow: var(--shadow-sm);
    }
    .toggle {
      display: inline-flex;
      padding: 0.25rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      background: var(--surface-2);
      gap: 0.2rem;
      margin-bottom: 1rem;
    }
    .toggle-btn {
      min-height: 38px;
      border: 0;
      border-radius: 999px;
      padding: 0.4rem 0.85rem;
      font: inherit;
      font-size: 0.88rem;
      font-weight: 600;
      color: var(--text-muted);
      background: transparent;
      cursor: pointer;
      transition: all 230ms var(--ease);
    }
    .toggle-btn.active {
      color: var(--primary-strong);
      background: white;
      box-shadow: var(--shadow-sm);
    }

    .flow-panel {
      display: none;
      grid-template-columns: 1.3fr 1fr;
      gap: 0.9rem;
      align-items: stretch;
    }
    .flow-panel.active { display: grid; animation: fadeUp 260ms var(--ease); }

    .media {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: linear-gradient(145deg, #fff, #f4f7ff);
      min-height: 220px;
      position: relative;
      overflow: hidden;
    }
    .media::before {
      content: "";
      position: absolute;
      inset: 14px;
      border-radius: 10px;
      border: 1px solid #e3e9ff;
      background: linear-gradient(160deg, #fff, #f2f5ff);
    }
    .media-tag {
      position: absolute;
      left: 22px;
      top: 22px;
      font-size: 0.73rem;
      font-weight: 600;
      color: var(--primary-strong);
      background: color-mix(in oklab, var(--primary) 12%, white);
      border: 1px solid color-mix(in oklab, var(--primary) 25%, white);
      padding: 0.25rem 0.45rem;
      border-radius: 999px;
    }
    .steps {
      border: 1px solid var(--border);
      border-radius: 14px;
      background: #fff;
      padding: 0.75rem;
      display: grid;
      gap: 0.5rem;
    }
    .step {
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 0.62rem;
      font-size: 0.86rem;
      color: var(--text-muted);
      transition: all 220ms var(--ease);
    }
    .step strong { color: var(--text); }
    .step:hover { transform: translateX(2px); border-color: color-mix(in oklab, var(--primary) 25%, white); }

    .tools-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.9rem;
    }
    .tool-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--surface);
      padding: 1rem;
      box-shadow: var(--shadow-sm);
      transition: transform 220ms var(--ease), box-shadow 220ms var(--ease);
    }
    .tool-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
    .tool-card h3 { margin: 0.3rem 0 0.35rem; font-size: 1rem; }
    .tool-card p { margin: 0; color: var(--text-muted); font-size: 0.9rem; }
    .tool-icon {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: var(--primary-soft);
      border: 1px solid color-mix(in oklab, var(--primary) 22%, white);
    }

    .testimonials-shell {
      overflow: hidden;
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      background: var(--surface);
      padding: 0.9rem;
    }
    .row-marquee { margin: 0.35rem 0; }
    .t-card {
      width: 320px;
      margin: 0 0.55rem;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: linear-gradient(180deg, #fff, #fbfcff);
      padding: 0.85rem;
      box-shadow: var(--shadow-sm);
    }
    .t-card p { margin: 0 0 0.7rem; color: var(--text-muted); font-size: 0.88rem; }
    .t-meta { display: flex; justify-content: space-between; align-items: center; font-size: 0.78rem; }
    .t-name { font-weight: 700; }

    .cta {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: linear-gradient(165deg, #fff, #f7f9ff);
      padding: clamp(1.3rem, 3vw, 2rem);
      box-shadow: var(--shadow-md);
      text-align: center;
    }
    .cta h2 { margin: 0; font-size: clamp(1.5rem, 3vw, 2.4rem); letter-spacing: -0.03em; }
    .cta p { margin: 0.75rem auto 1.1rem; max-width: 700px; color: var(--text-muted); }
    .icon-chip {
      width: 54px;
      height: 54px;
      border-radius: 14px;
      border: 1px solid var(--border);
      background: linear-gradient(160deg, #fff, #f3f6ff);
      margin: 0 0.5rem;
      display: grid;
      place-items: center;
      font-weight: 700;
      color: var(--text-muted);
      font-size: 0.8rem;
    }

    .footer {
      margin-top: 3rem;
      border-top: 1px solid var(--border);
      background: var(--surface);
      padding: 2.3rem 0;
    }
    .footer-top {
      display: grid;
      grid-template-columns: 1.3fr 1fr 1fr 1fr;
      gap: 1rem;
      margin-bottom: 1.2rem;
    }
    .footer h4 { margin: 0 0 0.5rem; font-size: 0.9rem; }
    .footer p, .footer a {
      margin: 0.35rem 0;
      color: var(--text-muted);
      font-size: 0.88rem;
    }
    .footer a:hover { color: var(--text); }
    .footer-bottom {
      border-top: 1px solid var(--border);
      padding-top: 0.8rem;
      color: var(--text-muted);
      font-size: 0.8rem;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 0.8rem;
    }

    @keyframes scroll {
      from { transform: translateX(0); }
      to { transform: translateX(-100%); }
    }
    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(8px); }
      to { opacity: 1; transform: translateY(0); }
    }

    @media (max-width: 1024px) {
      .preview-grid,
      .results-grid { grid-template-columns: repeat(3, 1fr); }
      .flow-panel { grid-template-columns: 1fr; }
      .tools-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-top { grid-template-columns: 1fr 1fr; }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .hero { padding-top: 3.2rem; }
      .stats-grid,
      .tools-grid,
      .preview-grid,
      .results-grid { grid-template-columns: repeat(2, 1fr); }
      .section-head { flex-direction: column; align-items: flex-start; }
      .footer-top { grid-template-columns: 1fr; }
      .t-card { width: 280px; }
    }

    @media (max-width: 520px) {
      .container { width: min(1120px, calc(100% - 1.2rem)); }
      .announcement .inner { height: auto; padding: 0.45rem 0; }
      .stats-grid,
      .preview-grid,
      .results-grid,
      .tools-grid { grid-template-columns: 1fr; }
      .hero-actions .btn { width: 100%; }
      .nav-cta .btn-primary { display: none; }
      .t-card { width: 250px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 1ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 1ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
<body>
  <div class="announcement" role="note" aria-label="announcement bar">
    <div class="container inner">
      <span class="badge">New</span>
      <span>Explore 615,900 screens across 1,150 apps — now with smarter flow discovery.</span>
    </div>
  </div>

  <header class="site-header">
    <div class="container nav">
      <a class="logo" href="index.html" aria-label="ScreenVault home">
        <span class="logo-mark" aria-hidden="true"></span>
        <span>ScreenVault</span>
      </a>
      <nav class="nav-links" aria-label="Main navigation">
        <a href="index.html">Pricing</a>
        <a href="index.html">Awards</a>
        <a href="index.html">Log in</a>
      </nav>
      <div class="nav-cta">
        <a class="btn btn-ghost" href="index.html">See our plans</a>
        <a class="btn btn-primary" href="index.html">Join for free</a>
      </div>
    </div>
  </header>

  <main>
    <section class="hero" aria-labelledby="hero-title">
      <div class="container">
        <span class="eyebrow">UI & UX reference, reimagined</span>
        <h1 id="hero-title">UI & UX design inspiration for mobile & web apps</h1>
        <p>Save hours of UI & UX research with a library of <strong>400,000+</strong> fully searchable mobile & web app screenshots.</p>
        <div class="hero-actions">
          <a href="index.html" class="btn btn-primary">Join for free</a>
          <a href="index.html" class="btn btn-ghost">See our plans</a>
        </div>
        <div class="hero-card" aria-hidden="true">
          <div class="preview-grid">
            <div class="preview-item"></div><div class="preview-item"></div><div class="preview-item"></div><div class="preview-item"></div>
            <div class="preview-item"></div><div class="preview-item"></div><div class="preview-item"></div><div class="preview-item"></div>
          </div>
        </div>
      </div>
    </section>

    <section aria-label="trusted by brands">
      <div class="container">
        <div class="section-head">
          <h2>Trusted by teams shipping great products</h2>
          <p>Used by designers and product teams at category-defining companies.</p>
        </div>
        <div class="trusted-track-wrap">
          <div class="marquee" style="--duration: 28s;">
            <div class="marquee-content" aria-hidden="true">
              <span class="brand-chip">Google</span><span class="brand-chip">Meta</span><span class="brand-chip">Stripe</span><span class="brand-chip">Airbnb</span><span class="brand-chip">Shopify</span><span class="brand-chip">Loom</span><span class="brand-chip">Mailchimp</span><span class="brand-chip">Twitch</span><span class="brand-chip">Spotify</span><span class="brand-chip">Apple TV</span><span class="brand-chip">Notion</span><span class="brand-chip">Dropbox</span>
