  <script>
    const resultsGrid = document.getElementById('resultsGrid');
    const tabButtons = Array.from(document.querySelectorAll('.tab'));
    const filterButtons = Array.from(document.querySelectorAll('.pill'));

    const tabCounts = {
      'Screens': 8,
      'UI Elements': 6,
      'Flows': 7,
      'Text in Screenshot': 5
    };

    let activeTab = 'Screens';
    let activeFilter = 'Profile';

    function renderResults() {
      const count = tabCounts[activeTab] || 6;
      const cards = Array.from({ length: count }, (_, i) => {
        const delay = i * 45;
        return `
          <article class="result-card" style="animation-delay:${delay}ms">
            <div class="result-thumb"></div>
            <div class="result-meta">
              <span>${activeTab}</span>
              <span>${activeFilter}</span>
            </div>
          </article>
        `;
      }).join('');
      resultsGrid.innerHTML = cards;
    }

    tabButtons.forEach((button) => {
      button.addEventListener('click', () => {
        activeTab = button.dataset.tab;
        tabButtons.forEach((b) => {
          const active = b === button;
          b.classList.toggle('active', active);
          b.setAttribute('aria-selected', String(active));
        });
        renderResults();
      });
    });

    filterButtons.forEach((button) => {
      button.addEventListener('click', () => {
        activeFilter = button.dataset.filter;
        filterButtons.forEach((b) => b.classList.toggle('active', b === button));
        renderResults();
      });
    });

    renderResults();

    const toggleButtons = Array.from(document.querySelectorAll('.toggle-btn'));
    const panels = Array.from(document.querySelectorAll('.flow-panel'));

    toggleButtons.forEach((button) => {
      button.addEventListener('click', () => {
        const mode = button.dataset.mode;
        toggleButtons.forEach((b) => {
          const active = b === button;
          b.classList.toggle('active', active);
          b.setAttribute('aria-selected', String(active));
        });
        panels.forEach((panel) => panel.classList.toggle('active', panel.dataset.panel === mode));
      });
    });

    function formatNumber(value) {
      return new Intl.NumberFormat('en-US').format(value);
    }

    function animateCounter(el) {
      const target = Number(el.dataset.counter || 0);
      const suffix = el.dataset.suffix || '';
      const duration = 1400;
      const start = performance.now();

      function frame(now) {
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(target * eased);
        el.textContent = `${formatNumber(current)}${suffix}`;
        if (progress < 1) requestAnimationFrame(frame);
      }

      requestAnimationFrame(frame);
    }

    const counters = Array.from(document.querySelectorAll('[data-counter]'));
    let countersStarted = false;
    const statsSection = document.getElementById('stats');

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry, index) => {
        if (entry.isIntersecting && !countersStarted) {
          countersStarted = true;
          counters.forEach((counter, i) => {
            setTimeout(() => animateCounter(counter), i * 180);
          });
        }
      });
    }, { threshold: 0.35 });

    if (statsSection) observer.observe(statsSection);
  </script>
